const crypto = require('crypto');

const secret = process.env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET env var not set on n8n container');

const rawBody = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data, 'base64').toString()
  : JSON.stringify($input.first().json);

const incomingSig = $input.first().headers?.['x-mf-signature'] ?? '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

if (incomingSig.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(incomingSig), Buffer.from(expected))) {
  throw new Error('HMAC signature mismatch — request rejected');
}

return $input.all();

const body = $input.first().json;

const required = ['org_id', 'externalPostId', 'platform', 'profileKey'];
const missing = required.filter(k => !body[k]);
if (missing.length) throw new Error(`Missing fields: ${missing.join(', ')}`);

// Ayrshare analytics accepts post id + platform
// Endpoint: GET /api/analytics/post?id=<postId>&platforms=<platform>
const PLATFORM_MAP = {
  x: 'twitter',
  instagram: 'instagram',
  facebook: 'facebook',
  linkedin: 'linkedin',
  youtube: 'youtube',
  tiktok: 'tiktok',
};
const ayrPlatform = PLATFORM_MAP[body.platform] ?? body.platform;

return [{
  json: {
    org_id: body.org_id,
    externalPostId: body.externalPostId,
    platform: body.platform,
    ayrPlatform,
    profileKey: body.profileKey,
  }
}];

const upstream = $('Validate Payload').first().json;
const ayrRes = $input.first().json;
const statusCode = $input.first().json?.statusCode ?? 200;

// Ayrshare analytics shape varies by platform; extract what is available.
// Typical success: { status:'success', analytics:{ likes, comments, views, shares, impressions, ... } }
// We normalise into a flat AnalyticsSnapshot-compatible object.

if (ayrRes.status !== 'success') {
  throw new Error(
    `Ayrshare analytics returned non-success: ${ayrRes.message ?? JSON.stringify(ayrRes)}`
  );
}

const a = ayrRes.analytics ?? {};

const snapshot = {
  platform: upstream.platform,
  externalPostId: upstream.externalPostId,
  views: a.views ?? a.videoViews ?? a.reach ?? null,
  likes: a.likes ?? a.favorites ?? null,
  comments: a.comments ?? null,
  shares: a.shares ?? a.retweets ?? null,
  impressions: a.impressions ?? null,
  capturedAt: new Date().toISOString(),
  raw: ayrRes.analytics ?? ayrRes,
};

return [{ json: snapshot }];

const upstream = $('Validate Payload').first()?.json ?? {};
const err = $input.first().json?.error ?? $input.first().json?.message ?? 'Unknown analytics error';

return [{
  json: {
    platform: upstream.platform ?? 'unknown',
    externalPostId: upstream.externalPostId ?? null,
    views: null,
    likes: null,
    comments: null,
    shares: null,
    impressions: null,
    capturedAt: new Date().toISOString(),
    raw: null,
    _error: String(err),
  }
}];
